import React, { createContext, useContext, useState, useEffect } from 'react';
import { getData, saveData } from '../services/localStorageService';
import { useAuth } from './AuthContext';

const WishlistContext = createContext();

export const WishlistProvider = ({ children }) => {
  const { currentUser } = useAuth();
  const [wishlist, setWishlist] = useState([]);

  useEffect(() => {
    if (currentUser) {
      const all = getData('wishlists');
      const userWishlist = all.find(w => w.userId === currentUser.id);
      setWishlist(userWishlist ? userWishlist.items : []);
    } else {
      setWishlist([]);
    }
  }, [currentUser]);

  const saveWishlist = (items) => {
    const all = getData('wishlists');
    const idx = all.findIndex(w => w.userId === currentUser.id);
    if (idx !== -1) {
      all[idx].items = items;
    } else {
      all.push({ userId: currentUser.id, items });
    }
    saveData('wishlists', all);
    setWishlist(items);
  };

  const addToWishlist = (destination) => {
    if (!currentUser) return false;
    if (wishlist.find(w => w.id === destination.id)) return false;
    const updated = [...wishlist, { ...destination, addedAt: new Date().toISOString() }];
    saveWishlist(updated);
    return true;
  };

  const removeFromWishlist = (destId) => {
    const updated = wishlist.filter(w => w.id !== destId);
    saveWishlist(updated);
  };

  const isInWishlist = (destId) => wishlist.some(w => w.id === destId);

  return (
    <WishlistContext.Provider value={{ wishlist, addToWishlist, removeFromWishlist, isInWishlist }}>
      {children}
    </WishlistContext.Provider>
  );
};

export const useWishlist = () => useContext(WishlistContext);
export default WishlistContext;
